package cz.zamerovac.app;
import android.content.*;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.util.*;

/** Immutable content-addressed backups, independent of pairing, sync settings and live media deletion. */
final class BackupHistory {
    interface Progress {void update(String phase,int completed,int total)throws Exception;}
    private final Context context;private final SharedPreferences prefs;private final BackupStore store;private final Progress progress;
    BackupHistory(Context context,SharedPreferences prefs,BackupStore store,Progress progress){this.context=context;this.prefs=prefs;this.store=store;this.progress=progress;}
    private void progress(String phase,int done,int total)throws Exception{if(progress!=null)progress.update(phase,done,total);}
    static String path(String device,String backup)throws IOException{if(!DeviceIdentity.valid(device)||!DeviceIdentity.valid(backup))throw new IOException("Neplatná identita zálohy");return "backups/v2/devices/"+device+"/"+backup+".json";}
    private static String blob(String hash)throws IOException{if(!hash.matches("[a-f0-9]{64}"))throw new IOException("Neplatný kontrolní součet zálohy");return "backups/v2/blobs/"+hash;}
    private static byte[] bytes(InputStream source,int limit)throws Exception{try(InputStream in=source;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] block=new byte[65536];int n;while((n=in.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Záloha přerušena");if(out.size()+n>limit)throw new IOException("Metadata zálohy překračují limit");out.write(block,0,n);}return out.toByteArray();}}
    private static JSONObject copy(InputStream in,OutputStream out,long limit)throws Exception{
        java.security.MessageDigest digest=ArchiveIntegrity.digest();long size=0;byte[] block=new byte[65536];int count;
        while((count=in.read(block))!=-1){if(Thread.currentThread().isInterrupted())throw new InterruptedIOException("Operace zálohy byla přerušena");size+=count;if(size>limit)throw new IOException("Blok zálohy překračuje deklarovanou velikost");out.write(block,0,count);digest.update(block,0,count);}return ArchiveIntegrity.entry(size,digest.digest());
    }
    private void verify(String path,String hash,long size)throws Exception{try(InputStream in=store.open(path)){JSONObject actual=copy(in,new OutputStream(){public void write(int b){}public void write(byte[] bytes,int off,int length){}},size);if(size!=actual.getLong("size")||!hash.equals(actual.getString("sha256")))throw new IOException("Poškozený nebo neúplný blok zálohy. Původní historie zůstává beze změny.");}}
    private interface Source {InputStream open()throws Exception;}
    private void put(String path,String hash,long size,Source source,boolean reuse)throws Exception{
        if(reuse)try{verify(path,hash,size);return;}catch(FileNotFoundException missing){/* Only proven absence permits create; never overwrite a damaged historical blob. */}
        try(InputStream in=source.open();OutputStream out=store.create(path)){JSONObject actual=copy(in,out,size);out.flush();if(actual.getLong("size")!=size||!hash.equals(actual.getString("sha256")))throw new IOException("Zdroj zálohy se změnil. Historický bod nebyl potvrzen.");}
        verify(path,hash,size);
    }
    JSONObject create()throws Exception{
        progress("Kontroluji úplnost",0,0);PeerSnapshot snapshot=PeerSnapshot.capture(context,prefs);byte[] project=CausalClock.canonical(snapshot.data).getBytes(StandardCharsets.UTF_8);String projectHash=PeerWire.hash(project);put(blob(projectHash),projectHash,project.length,()->new ByteArrayInputStream(project),true);
        int done=0;JSONArray media=new JSONArray();for(JSONObject entry:snapshot.media.values()){progress("Ukládám a ověřuji přílohy",done,snapshot.media.size());File source=new File(context.getFilesDir(),"media/"+entry.getString("id"));put(blob(entry.getString("hash")),entry.getString("hash"),entry.getLong("size"),()->new FileInputStream(source),true);media.put(new JSONObject(entry.toString()));done++;}
        // Publish only after a final completeness pass. External providers can still lose data later.
        progress("Ověřuji všechny bloky",0,media.length()+1);verify(blob(projectHash),projectHash,project.length);for(int i=0;i<media.length();i++){JSONObject entry=media.getJSONObject(i);verify(blob(entry.getString("hash")),entry.getString("hash"),entry.getLong("size"));progress("Ověřuji všechny bloky",i+1,media.length()+1);}
        String device=DeviceIdentity.get(context.getNoBackupFilesDir()),backup=UUID.randomUUID().toString(),model=android.os.Build.MODEL==null?"Android":android.os.Build.MODEL;model=model.replaceAll("[\\p{Cntrl}]","");if(model.length()>80)model=model.substring(0,80);
        JSONObject manifest=new JSONObject().put("format","cz.zamerovac.backup").put("version",2).put("deviceId",device).put("backupId",backup).put("deviceName",model).put("createdAt",java.time.Instant.now().toString()).put("project",new JSONObject().put("hash",projectHash).put("size",project.length)).put("media",media);byte[] encoded=CausalClock.canonical(manifest).getBytes(StandardCharsets.UTF_8);String path=path(device,backup);put(path,PeerWire.hash(encoded),encoded.length,()->new ByteArrayInputStream(encoded),false);progress("Historický bod je ověřený",done,done);return manifest;
    }
    private JSONObject manifest(String path)throws Exception{
        if(path==null||!path.matches("backups/v2/devices/[a-f0-9-]{36}/[a-f0-9-]{36}\\.json"))throw new IOException("Neplatná cesta historické zálohy");byte[] encoded=bytes(store.open(path),PeerWire.MAX_JSON);String text=JsonInput.decode(encoded);JsonInput.check(text);new org.erdtman.jcs.JsonCanonicalizer(text);JSONObject manifest=JsonInput.object(encoded);
        if(!"cz.zamerovac.backup".equals(manifest.optString("format"))||PeerSnapshot.integer(manifest,"version",2)!=2||!path.equals(path(manifest.getString("deviceId"),manifest.getString("backupId"))))throw new IOException("Neplatný nebo cizí manifest zálohy");java.time.Instant.parse(manifest.getString("createdAt"));String name=manifest.optString("deviceName","Android");if(name.length()>80||name.matches(".*[\\p{Cntrl}].*"))throw new IOException("Neplatný název zařízení v záloze");JSONObject project=manifest.getJSONObject("project");blob(project.getString("hash"));if(PeerSnapshot.integer(project,"size",PeerWire.MAX_JSON)<1||manifest.getJSONArray("media").length()>20000)throw new IOException("Neplatná velikost zálohy");return manifest;
    }
    JSONObject list()throws Exception{
        JSONArray histories=new JSONArray();int count=0;for(BackupStore.Entry device:store.list("backups/v2/devices")){if(!device.directory||!DeviceIdentity.valid(device.name))continue;for(BackupStore.Entry entry:store.list("backups/v2/devices/"+device.name)){if(++count>10000)throw new IOException("Historie záloh je příliš velká");if(entry.directory||!entry.name.matches("[a-f0-9-]{36}\\.json"))continue;String path="backups/v2/devices/"+device.name+"/"+entry.name;JSONObject item=new JSONObject().put("path",path).put("deviceId",device.name).put("verified",false);try{JSONObject manifest=manifest(path);item.put("createdAt",manifest.getString("createdAt")).put("deviceName",manifest.optString("deviceName","Android")).put("files",manifest.getJSONArray("media").length()).put("state","Obsah ověřit před obnovou");}catch(Exception invalid){item.put("state","Manifest nelze ověřit").put("error",true);}histories.put(item);}}
        long occupied=0;boolean approximate=false;for(BackupStore.Entry entry:store.list("backups/v2/blobs")){if(!entry.directory){if(entry.size<0)approximate=true;else occupied+=entry.size;}}return new JSONObject().put("histories",histories).put("occupiedBytes",occupied).put("occupiedApproximate",approximate).put("deviceId",DeviceIdentity.get(context.getNoBackupFilesDir()));
    }
    JSONObject check(String path)throws Exception{JSONObject manifest=manifest(path);JSONObject project=manifest.getJSONObject("project");byte[] projectBytes=bytes(store.open(blob(project.getString("hash"))),PeerWire.MAX_JSON);if(projectBytes.length!=project.getLong("size")||!project.getString("hash").equals(PeerWire.hash(projectBytes)))throw new IOException("Poškozená databáze historické zálohy");
        JSONObject data=JsonInput.object(projectBytes);JSONObject wire=new JSONObject().put("format","cz.zamerovac.sync.snapshot").put("version",2).put("sourceId",manifest.getString("deviceId")).put("data",data).put("media",manifest.getJSONArray("media"));PeerSnapshot validated=PeerSnapshot.parse(CausalClock.canonical(wire).getBytes(StandardCharsets.UTF_8),manifest.getString("deviceId"));int done=0;for(JSONObject entry:validated.media.values()){verify(blob(entry.getString("hash")),entry.getString("hash"),entry.getLong("size"));progress("Ověřuji historickou zálohu",++done,validated.media.size());}return manifest;
    }
    BackupImporter.Result restore(String path)throws Exception{
        JSONObject manifest=manifest(path),project=manifest.getJSONObject("project");byte[] raw=bytes(store.open(blob(project.getString("hash"))),PeerWire.MAX_JSON);if(raw.length!=project.getLong("size")||!project.getString("hash").equals(PeerWire.hash(raw)))throw new IOException("Kontrola databáze zálohy selhala");JSONObject source=JsonInput.object(raw);
        JSONObject wire=new JSONObject().put("format","cz.zamerovac.sync.snapshot").put("version",2).put("sourceId",manifest.getString("deviceId")).put("data",source).put("media",manifest.getJSONArray("media"));PeerSnapshot snapshot=PeerSnapshot.parse(CausalClock.canonical(wire).getBytes(StandardCharsets.UTF_8),manifest.getString("deviceId"));File stage=new File(context.getCacheDir(),"history-restore-"+UUID.randomUUID());if(!stage.mkdirs())throw new IOException("Není místo pro přípravu obnovy");Map<String,File> files=new HashMap<>();JSONObject metadata=new JSONObject();
        try{int done=0;for(JSONObject entry:snapshot.media.values()){String id=entry.getString("id");File file=new File(stage,id);try(InputStream in=store.open(blob(entry.getString("hash")));FileOutputStream out=new FileOutputStream(file)){JSONObject actual=copy(in,out,entry.getLong("size"));out.getFD().sync();if(actual.getLong("size")!=entry.getLong("size")||!actual.getString("sha256").equals(entry.getString("hash")))throw new IOException("Příloha zálohy je poškozená. Obnova nebyla provedena.");}files.put(id,file);metadata.put(id,entry);progress("Připravuji bezpečnou obnovu",++done,snapshot.media.size());}
            synchronized(TrashPurger.LOCK){String saved=LocalDatabase.read(context.getFilesDir());JSONObject current=saved.isEmpty()?new JSONObject().put("schema",1).put("records",new JSONArray()):new JSONObject(saved);BackupImporter.Result result=BackupImporter.restoreVerified(context,current,prefs,source,metadata,files);try{LocalDatabase.write(context.getFilesDir(),result.data.toString());}catch(Exception failure){result.rollback(context,prefs);throw failure;}return result;}
        }finally{File[] remaining=stage.listFiles();if(remaining!=null)for(File file:remaining)file.delete();stage.delete();}
    }
}
